package com.tencent.weknora.knowledge;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import com.tencent.weknora.task.*;
import java.sql.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.CancellationException;
import org.springframework.jdbc.core.*;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;

/** Existing Go tags and additive relations. No DDL and no pending-counter ownership. */
public final class KnowledgeAutoTagRepository {
  private final JdbcTemplate jdbc;private final ObjectMapper json;private final KnowledgeRepository knowledge;private final TransactionTemplate tx;private final Clock clock;private final boolean postgres;
  public KnowledgeAutoTagRepository(JdbcTemplate jdbc,ObjectMapper json,KnowledgeRepository knowledge,PlatformTransactionManager manager,Clock clock){this.jdbc=jdbc;this.json=json;this.knowledge=knowledge;tx=new TransactionTemplate(manager);this.clock=clock;postgres=Boolean.TRUE.equals(jdbc.execute((ConnectionCallback<Boolean>)c->c.getMetaData().getDatabaseProductName().equals("PostgreSQL")));}
  public ObjectNode knowledge(TaskRecord job){var rows=jdbc.queryForList("SELECT tenant_id FROM knowledges WHERE id=? AND deleted_at IS NULL",job.payload().path("knowledge_id").asText());if(rows.isEmpty())throw new IllegalStateException("knowledge not found");if(number(rows.getFirst().get("tenant_id"))!=job.tenantId())return null;return knowledge.get(job.tenantId(),job.payload().path("knowledge_id").asText()).orElseThrow();}
  public ObjectNode base(TaskRecord job){var rows=jdbc.queryForList("SELECT tenant_id FROM knowledge_bases WHERE id=? AND deleted_at IS NULL",job.payload().path("knowledge_base_id").asText());if(rows.isEmpty())throw new IllegalStateException("knowledge base not found");if(number(rows.getFirst().get("tenant_id"))!=job.tenantId())return null;return knowledge.knowledgeBase(job.tenantId(),job.payload().path("knowledge_base_id").asText());}
  public boolean superseded(TaskRecord job){long attempt=job.payload().path("attempt").asLong();if(attempt<=0)return false;Long latest=jdbc.queryForObject("SELECT COALESCE(MAX(s.attempt),0) FROM knowledge_processing_spans s JOIN knowledges k ON k.id=s.knowledge_id WHERE k.tenant_id=? AND k.id=? AND k.deleted_at IS NULL",Long.class,job.tenantId(),job.payload().path("knowledge_id").asText());return latest!=null&&latest>attempt;}
  public record Candidates(List<ObjectNode> tags,long total){}
  public Candidates candidates(TaskRecord job){Object[] values={job.tenantId(),job.payload().path("knowledge_base_id").asText()};Long total=jdbc.queryForObject("SELECT COUNT(*) FROM knowledge_tags WHERE tenant_id=? AND knowledge_base_id=?",Long.class,values);return new Candidates(rows("SELECT id,name FROM knowledge_tags WHERE tenant_id=? AND knowledge_base_id=? ORDER BY sort_order ASC,created_at DESC,seq_id DESC LIMIT 500",values),total==null?0:total);}
  public List<String> existing(TaskRecord job){return jdbc.queryForList("SELECT kt.id FROM knowledge_tag_relations ktr JOIN knowledge_tags kt ON kt.id=ktr.tag_id WHERE ktr.knowledge_id=?",String.class,job.payload().path("knowledge_id").asText());}
  // Go ListChunksByKnowledgeID is text-only, despite the helper accepting image kinds.
  public List<ObjectNode> chunks(TaskRecord job){return rows("SELECT id,tenant_id,knowledge_id,knowledge_base_id,content,content_revision,chunk_type,chunk_index,start_at,is_enabled FROM chunks WHERE tenant_id=? AND knowledge_id=? AND chunk_type='text' AND deleted_at IS NULL ORDER BY chunk_index ASC",job.tenantId(),job.payload().path("knowledge_id").asText());}
  public boolean bound(TaskRecord job,List<ObjectNode> chunks){return chunks.stream().allMatch(c->c.path("tenant_id").asLong()==job.tenantId()&&c.path("knowledge_id").equals(job.payload().path("knowledge_id"))&&c.path("knowledge_base_id").equals(job.payload().path("knowledge_base_id")));}
  public boolean current(TaskRecord job,List<ObjectNode> original,List<ObjectNode> fresh){if(original.size()!=fresh.size()||!bound(job,fresh))return false;var byId=new HashMap<String,ObjectNode>();fresh.forEach(c->byId.put(c.path("id").asText(),c));for(var c:original){var n=byId.get(c.path("id").asText());if(n==null)return false;for(String key:List.of("content","content_revision","is_enabled","chunk_type","start_at"))if(!c.path(key).equals(n.path(key)))return false;}return true;}
  public void add(TaskRecord job,List<String> ids){tx.executeWithoutResult(s->{fence(job);String id=job.payload().path("knowledge_id").asText(),kb=job.payload().path("knowledge_base_id").asText();var states=jdbc.queryForList("SELECT parse_status FROM knowledges WHERE tenant_id=? AND id=? AND knowledge_base_id=? AND deleted_at IS NULL"+(postgres?" FOR UPDATE":""),job.tenantId(),id,kb);if(states.isEmpty()||Set.of("cancelled","deleting","failed").contains(states.getFirst().get("parse_status")))throw new IllegalStateException("knowledge is unavailable for automatic tagging");for(String tag:ids){Integer count=jdbc.queryForObject("SELECT COUNT(*) FROM knowledge_tags WHERE tenant_id=? AND knowledge_base_id=? AND id=?",Integer.class,job.tenantId(),kb,tag);if(count==null||count!=1)throw new IllegalStateException("automatic tag no longer belongs to knowledge base");}for(String tag:ids)jdbc.update("INSERT INTO knowledge_tag_relations(knowledge_id,tag_id,created_at) VALUES(?,?,?) ON CONFLICT(knowledge_id,tag_id) DO NOTHING",id,tag,postgres?Timestamp.from(clock.instant()):clock.instant().toString());fence(job);});}
  private void fence(TaskRecord job){var rows=jdbc.queryForList("SELECT status,attempts,lease_owner,lease_until,cancel_requested FROM java_task_jobs WHERE tenant_id=? AND id=?"+(postgres?" FOR UPDATE":""),job.tenantId(),job.id());if(rows.isEmpty())throw new CancellationException("automatic tag lease unavailable");var r=rows.getFirst();if(!Objects.equals(r.get("status"),"running")||number(r.get("attempts"))!=job.attempts()||!Objects.equals(r.get("lease_owner"),job.leaseOwner())||number(r.get("lease_until"))<=clock.millis()||Boolean.TRUE.equals(r.get("cancel_requested"))||number(r.get("cancel_requested"))!=0)throw new CancellationException("automatic tag lease lost or canceled");if(superseded(job))throw new CancellationException("automatic tag attempt superseded");}
  private List<ObjectNode> rows(String sql,Object... args){return jdbc.query(sql,(rs,n)->{var out=json.createObjectNode();var md=rs.getMetaData();for(int i=1;i<=md.getColumnCount();i++){String key=md.getColumnLabel(i);Object v=rs.getObject(i);if(v==null)out.putNull(key);else if(key.equals("is_enabled"))out.put(key,rs.getBoolean(i));else if(v instanceof Number number)out.put(key,number.longValue());else out.put(key,v.toString());}return out;},args);}
  private static long number(Object v){return v instanceof Number n?n.longValue():0;}
}
